-- T-SEC-1 … T-SEC-6, T-SEC-8: claim access.
begin;
select plan(18);
insert into auth.users (id, instance_id, aud, role, email, raw_user_meta_data, raw_app_meta_data) values
 ('10000000-0000-4000-8000-000000000021','00000000-0000-0000-0000-000000000000','authenticated','authenticated','sub@example.com','{"account_type":"claimant","first_name":"S","surname":"C","popia_consent":true}','{}');
insert into public.claims (id,claimant_id,created_by,status) values ('14000000-0000-4000-8000-000000000001','b0000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','submitted');
set local role authenticated;
set local "request.jwt.claims" = '{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated"}';
select isnt_empty($$ select 1 from public.claims where id='c0000000-0000-4000-8000-000000000002' $$,'T-SEC-1a claimant reads own claim');
select is_empty($$ select 1 from public.claims where id='c0000000-0000-4000-8000-000000000003' $$,'T-SEC-1b claimant cannot read the second claimant''s claim');
update public.claims set injuries_summary='edited by owner' where id='c0000000-0000-4000-8000-000000000002';
select is((select injuries_summary from public.claims where id='c0000000-0000-4000-8000-000000000002'),'edited by owner','T-SEC-8a claimant updates own pre-submission claim');
update public.claims set injuries_summary='intrusion' where id='c0000000-0000-4000-8000-000000000003';
update public.claims set injuries_summary='too late' where id='14000000-0000-4000-8000-000000000001';
select is_empty($$ select 1 from public.claims where id='14000000-0000-4000-8000-000000000001' and injuries_summary='too late' $$,'T-SEC-8b claimant cannot update a submitted claim');
select throws_ok($$ update public.claims set reference='CG-2026-999999' where id='c0000000-0000-4000-8000-000000000002' $$,'42501',null,'T-SEC-8b claimant cannot change the reference');
reset role;
select is_empty($$ select 1 from public.claims where id='c0000000-0000-4000-8000-000000000003' and injuries_summary='intrusion' $$,'T-SEC-8b claimant cannot update another claim');
set local role authenticated;
set local "request.jwt.claims" = '{"sub":"00000000-0000-4000-8000-000000000003","role":"authenticated"}';
select isnt_empty($$ select 1 from public.claims where id='c0000000-0000-4000-8000-000000000003' $$,'T-SEC-2a lawyer reads an authorised client''s claim');
select is_empty($$ select 1 from public.claims where id='c0000000-0000-4000-8000-000000000004' $$,'T-SEC-2b lawyer cannot read a claim of the second firm');
set local "request.jwt.claims" = '{"sub":"00000000-0000-4000-8000-000000000005","role":"authenticated"}';
select isnt_empty($$ select 1 from public.claims where id='c0000000-0000-4000-8000-000000000001' $$,'T-SEC-3a officer reads an assigned claim');
select is_empty($$ select 1 from public.claims where id='c0000000-0000-4000-8000-000000000002' $$,'T-SEC-3b officer cannot read an unassigned claim');
set local "request.jwt.claims" = '{"sub":"00000000-0000-4000-8000-000000000006","role":"authenticated"}';
select isnt_empty($$ select 1 from public.claims where id='c0000000-0000-4000-8000-000000000005' $$,'T-SEC-4a investigator reads a claim with an alert assigned to them');
select is_empty($$ select 1 from public.claims where id='c0000000-0000-4000-8000-000000000001' $$,'T-SEC-4b investigator cannot read a claim without one');
set local "request.jwt.claims" = '{"sub":"00000000-0000-4000-8000-000000000007","role":"authenticated"}';
select isnt_empty($$ select 1 from public.claim_summaries $$,'T-SEC-5a manager reads claim_summaries');
select is_empty($$ select 1 from public.claims union all select 1 from public.claimants union all select 1 from public.documents $$,'T-SEC-5b manager gets no rows from claims, claimants or documents');
select is_empty($$ select 1 from information_schema.columns where table_schema='public' and table_name='claim_summaries' and column_name in ('first_name','surname','id_number','email','mobile','claimant_name') $$,'T-SEC-5b claim_summaries has no personal details');
set local "request.jwt.claims" = '{"sub":"00000000-0000-4000-8000-000000000008","role":"authenticated"}';
select isnt_empty($$ select 1 from public.claim_summaries $$,'T-SEC-6a admin reads claim_summaries');
select is_empty($$ select 1 from public.documents union all select 1 from public.risk_evidence union all select 1 from public.investigation_notes $$,'T-SEC-6b admin gets no documents, evidence or notes');
set local "request.jwt.claims" = '{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated"}';
select is_empty($$ select 1 from public.claim_summaries $$,'T-SEC-5b a claimant gets no rows from claim_summaries');
reset role;
select * from finish();
rollback;
